for old, new in replacements.items():
    text = text.replace(old, new)

video_start = text.find('<h3 class="update-subheading">🎥 Видео про Юстуса</h3>')
if video_start != -1:
    source_start = text.find('<div class="update-source-links">', video_start)
    if source_start == -1:
        raise SystemExit('Source links marker after Justus video not found')
    text = text[:video_start] + text[source_start:]

text = text.replace('<a href="https://www.youtube.com/watch?v=4PYbbSMGy-s" rel="noopener noreferrer" target="_blank">▶️ Открыть на YouTube</a>\n', '')

path.write_text(text, encoding='utf-8')
print('Cleaned Justus page and removed embedded video.')
